"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["37"],{25249(e){e.exports=JSON.parse('{"id":"FIN-612","slug":"earnings-management","term":"Earnings Management","also_known_as":[],"difficulty":"Intermediate","definition":"Earnings management is the use of accounting choices, estimates or the timing of real business decisions to present reported profits in a particular way, often to meet targets or smooth results.","explanation":["Accounting involves many judgments, such as estimating bad debts, warranty costs or asset lives, and choosing when to recognise certain items. Managers can use this flexibility to influence reported earnings.","Earnings management can take two forms. Accounting-based management uses estimates and policy choices, for example releasing an excessive provision to boost profit in a weak year. Real earnings management changes actual business decisions, such as cutting research or marketing spending at the end of a quarter or offering heavy discounts to pull sales forward.","For example, a company slightly short of analysts\' profit forecasts might reduce its estimate of warranty costs to close the gap.","Some earnings management stays within accounting rules, although it may still mislead investors about a company\'s underlying performance. When it crosses into deliberately false reporting, it becomes accounting fraud.","Investors look for warning signs, such as profits that consistently just beat forecasts, large gaps between profit and operating cash flow, frequent changes in estimates and unusual movements in provisions. High-quality earnings are those that reflect real, sustainable performance and are backed by cash."],"note":"","total":1725,"prev":{"slug":"earnings-guidance","term":"Earnings Guidance"},"next":{"slug":"earnings-per-share","term":"Earnings Per Share (EPS)"}}')}}]);